code.cpp:
class Solution {
public:
    bool canCross(vector<int>& stones) {
        int n = stones.size();
        unordered_map<long long, unordered_set<int>> dp;
        for (int s : stones) dp[s] = {};
        dp[0].insert(0);
        for (int i = 0; i < n; i++) {
            long long pos = stones[i];
            for (int k : dp[pos]) {
                for (int step = k - 1; step <= k + 1; step++) {
                    if (step > 0 && dp.count(pos + step)) {
                        dp[pos + step].insert(step);
                    }
                }
            }
        }
        return !dp[stones[n - 1]].empty();
    }
};
